import { Dataset, Review, ReviewsResponse, Summary, RateLimitStatus, ChatMessage } from '@/types'

const API_BASE = '/api/v1'

function getToken(): string | null {
  if (typeof window === 'undefined') return null
  return sessionStorage.getItem('rl_token')
}

async function apiFetch<T>(path: string, options: RequestInit = {}): Promise<T> {
  const token = getToken()
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...(options.headers as Record<string, string> || {}),
  }
  if (token) headers['Authorization'] = `Bearer ${token}`

  const res = await fetch(`${API_BASE}${path}`, { ...options, headers })

  if (res.status === 401) {
    sessionStorage.removeItem('rl_token')
    sessionStorage.removeItem('rl_user')
    window.location.href = '/login?expired=1'
    throw new Error('Unauthorized')
  }

  if (!res.ok) {
    const err = await res.json().catch(() => ({ message: 'Request failed' }))
    throw Object.assign(new Error(err.message || 'Request failed'), { status: res.status, data: err })
  }

  if (res.status === 204) return undefined as T
  return res.json()
}

// Auth
export const authApi = {
  login: async (email: string, password: string) => {
    const res = await fetch(`${API_BASE}/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
    })
    if (!res.ok) {
      const err = await res.json().catch(() => ({ message: 'Login failed' }))
      throw Object.assign(new Error(err.message || 'Login failed'), { status: res.status, data: err })
    }
    return res.json() as Promise<{ token: string; expires_at: string; user: { id: string; email: string } }>
  },
  logout: () => apiFetch<void>('/auth/logout', { method: 'POST' }),
}

// Datasets
export const datasetsApi = {
  list: () => apiFetch<{ datasets: Dataset[] }>('/datasets'),
  get: (id: string) => apiFetch<Dataset>(`/datasets/${id}`),
  create: (input: string) =>
    apiFetch<{ id: string; asin: string; status: string }>('/datasets', {
      method: 'POST',
      body: JSON.stringify({ input }),
    }),
  upload: async (file: File): Promise<{ id: string; status: string }> => {
    const token = getToken()
    const headers: Record<string, string> = {}
    if (token) headers['Authorization'] = `Bearer ${token}`
    const body = new FormData()
    body.append('file', file)
    const res = await fetch(`${API_BASE}/datasets/upload`, { method: 'POST', headers, body })
    if (res.status === 401) {
      sessionStorage.removeItem('rl_token')
      sessionStorage.removeItem('rl_user')
      window.location.href = '/login?expired=1'
      throw new Error('Unauthorized')
    }
    if (!res.ok) {
      const err = await res.json().catch(() => ({ message: 'Upload failed' }))
      throw Object.assign(new Error(err.message || 'Upload failed'), { status: res.status, data: err })
    }
    return res.json()
  },
  rescrape: (id: string) =>
    apiFetch<{ status: string }>(`/datasets/${id}/rescrape`, { method: 'POST' }),
  delete: (id: string) => apiFetch<void>(`/datasets/${id}`, { method: 'DELETE' }),
}

// Reviews & Summary
export const reviewsApi = {
  list: (id: string, params: Record<string, string | number>) => {
    const qs = new URLSearchParams(Object.entries(params).map(([k, v]) => [k, String(v)])).toString()
    return apiFetch<ReviewsResponse>(`/datasets/${id}/reviews?${qs}`)
  },
  summary: (id: string) => apiFetch<Summary>(`/datasets/${id}/summary`),
}

// Rate limit
export const scrapeApi = {
  rateLimit: () => apiFetch<RateLimitStatus>('/scrape/rate-limit'),
}

// Chat
export const chatApi = {
  send: (datasetId: string, message: string, history: ChatMessage[]) =>
    apiFetch<{ reply: string; scope_refused: boolean }>(`/datasets/${datasetId}/chat`, {
      method: 'POST',
      body: JSON.stringify({
        message,
        history: history.map(h => ({ role: h.role, content: h.content })),
      }),
    }),
}

/** @type {import('next').NextConfig} */
const nextConfig = {
  async rewrites() {
    return [
      {
        source: '/api/:path*',
        destination: `${process.env.BACKEND_URL || 'http://localhost:9000'}/api/:path*`,
      },
    ]
  },
}

module.exports = nextConfig

'use client'

import { useState } from 'react'
import Link from 'next/link'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { AuthGuard } from '@/components/layout/AuthGuard'
import { TopNav } from '@/components/layout/TopNav'
import { StatusBadge } from '@/components/ui/StatusBadge'
import { Toast } from '@/components/ui/Toast'
import { datasetsApi, scrapeApi } from '@/lib/api'
import { Dataset } from '@/types'
import { Plus, MoreHorizontal, Inbox } from 'lucide-react'

function formatDate(s: string | null) {
  if (!s) return '—'
  try { return new Date(s).toLocaleDateString() } catch { return s }
}

function ActionMenu({ dataset, onDelete, onRescrape }: { dataset: Dataset; onDelete: () => void; onRescrape: () => void }) {
  const [open, setOpen] = useState(false)
  return (
    <div className="relative">
      <button onClick={() => setOpen(o => !o)} className="p-1 hover:bg-raised rounded" aria-label="Actions">
        <MoreHorizontal size={16} className="text-text-secondary" />
      </button>
      {open && (
        <div className="absolute right-0 mt-1 w-36 bg-white border border-border rounded-lg shadow-lg py-1 z-10">
          <Link href={`/datasets/${dataset.id}`} onClick={() => setOpen(false)} className="block px-3 py-2 text-sm text-text-primary hover:bg-raised">View</Link>
          <button onClick={() => { setOpen(false); onRescrape() }} className="w-full text-left px-3 py-2 text-sm text-text-primary hover:bg-raised" disabled={dataset.status === 'scraping'}>Re-scrape</button>
          <div className="border-t border-border my-1" />
          <button onClick={() => { setOpen(false); onDelete() }} className="w-full text-left px-3 py-2 text-sm text-error hover:bg-raised" disabled={dataset.status === 'scraping'}>Delete</button>
        </div>
      )}
    </div>
  )
}

function ConfirmDialog({ name, onConfirm, onCancel }: { name: string; onConfirm: () => void; onCancel: () => void }) {
  return (
    <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50">
      <div className="bg-white rounded-xl shadow-xl p-6 max-w-sm w-full mx-4">
        <h2 className="text-base font-semibold mb-2">Delete dataset?</h2>
        <p className="text-sm text-text-secondary mb-6">Deleting <strong>{name}</strong> will permanently remove all reviews and chat history. This cannot be undone.</p>
        <div className="flex gap-3 justify-end">
          <button onClick={onCancel} className="px-4 py-2 text-sm border border-border rounded-lg hover:bg-raised">Cancel</button>
          <button onClick={onConfirm} className="px-4 py-2 text-sm bg-error text-white rounded-lg hover:opacity-90">Delete</button>
        </div>
      </div>
    </div>
  )
}

export default function DatasetsPage() {
  const qc = useQueryClient()
  const [toast, setToast] = useState<{ msg: string; type: 'success' | 'error' } | null>(null)
  const [search, setSearch] = useState('')
  const [deleteTarget, setDeleteTarget] = useState<Dataset | null>(null)

  const { data, isLoading } = useQuery({
    queryKey: ['datasets'],
    queryFn: datasetsApi.list,
    refetchInterval: (query) => {
      const hasActive = query.state.data?.datasets?.some(d => d.status === 'scraping' || d.status === 'pending')
      return hasActive ? 5000 : 30000
    },
  })

  const { data: rateLimit } = useQuery({
    queryKey: ['rate-limit'],
    queryFn: scrapeApi.rateLimit,
    refetchInterval: 30000,
  })

  const deleteMutation = useMutation({
    mutationFn: datasetsApi.delete,
    onSuccess: () => { qc.invalidateQueries({ queryKey: ['datasets'] }); setToast({ msg: 'Dataset deleted.', type: 'success' }) },
    onError: (e: any) => setToast({ msg: e?.data?.message || 'Delete failed.', type: 'error' }),
  })

  const rescrapeMutation = useMutation({
    mutationFn: datasetsApi.rescrape,
    onSuccess: (_, id) => { qc.invalidateQueries({ queryKey: ['datasets'] }); setToast({ msg: 'Scraping started.', type: 'success' }) },
    onError: (e: any) => setToast({ msg: e?.data?.message || 'Re-scrape failed.', type: 'error' }),
  })

  const datasets = data?.datasets ?? []
  const filtered = search ? datasets.filter(d => (d.product_name || d.asin).toLowerCase().includes(search.toLowerCase()) || d.asin.toLowerCase().includes(search.toLowerCase())) : datasets

  return (
    <AuthGuard>
      <div className="flex flex-col min-h-screen">
        <TopNav />
        {toast && <Toast message={toast.msg} type={toast.type} onDismiss={() => setToast(null)} />}
        {deleteTarget && (
          <ConfirmDialog
            name={deleteTarget.product_name || deleteTarget.asin}
            onConfirm={() => { deleteMutation.mutate(deleteTarget.id); setDeleteTarget(null) }}
            onCancel={() => setDeleteTarget(null)}
          />
        )}

        {rateLimit?.suspended && (
          <div className="bg-warning-bg border-b border-warning/20 px-6 py-2 text-sm text-warning" role="alert">
            Scraping is suspended. Daily review limit reached. Scraping resumes at {rateLimit.next_scrape_available_at ? new Date(rateLimit.next_scrape_available_at).toLocaleString() : '—'}.
          </div>
        )}

        <main className="flex-1 px-6 py-6 max-w-6xl mx-auto w-full">
          <div className="flex items-center justify-between mb-6">
            <h1 className="text-2xl font-semibold text-text-primary">Datasets</h1>
            <div className="flex items-center gap-3">
              <input
                type="search"
                placeholder="Search datasets…"
                value={search}
                onChange={e => setSearch(e.target.value)}
                className="w-64 px-3 py-1.5 border border-border rounded-lg text-sm bg-raised focus:outline-none focus:ring-2 focus:ring-accent"
              />
              <Link href="/datasets/new" className="inline-flex items-center gap-1.5 bg-accent hover:bg-accent-hover text-white text-sm font-medium px-4 py-2 rounded-lg transition-colors">
                <Plus size={16} /> New Dataset
              </Link>
            </div>
          </div>

          {isLoading ? (
            <div className="space-y-2">
              {[1,2,3].map(i => <div key={i} className="h-12 bg-raised rounded-lg animate-pulse" />)}
            </div>
          ) : filtered.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 text-center">
              <Inbox size={40} className="text-text-disabled mb-4" />
              <h2 className="text-base font-medium text-text-primary mb-1">No datasets yet</h2>
              <p className="text-sm text-text-secondary mb-4">Add your first Amazon product to get started.</p>
              <Link href="/datasets/new" className="inline-flex items-center gap-1.5 bg-accent text-white text-sm font-medium px-4 py-2 rounded-lg">
                <Plus size={16} /> New Dataset
              </Link>
            </div>
          ) : (
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-border text-left text-text-secondary text-xs font-semibold uppercase tracking-wide">
                  <th className="pb-3 pr-4">Product</th>
                  <th className="pb-3 pr-4">ASIN</th>
                  <th className="pb-3 pr-4">Status</th>
                  <th className="pb-3 pr-4">Reviews</th>
                  <th className="pb-3 pr-4 whitespace-nowrap">Updated</th>
                  <th className="pb-3" />
                </tr>
              </thead>
              <tbody>
                {filtered.map(ds => (
                  <tr key={ds.id} className="border-b border-border hover:bg-raised/50 transition-colors">
                    <td className="py-3 pr-4 font-medium text-text-primary">
                      <Link href={`/datasets/${ds.id}`} className="hover:text-accent">{ds.product_name || ds.asin}</Link>
                    </td>
                    <td className="py-3 pr-4 font-mono text-xs text-text-secondary">{ds.asin}</td>
                    <td className="py-3 pr-4"><StatusBadge status={ds.status} /></td>
                    <td className="py-3 pr-4 text-text-secondary">{ds.review_count ?? '—'}</td>
                    <td className="py-3 pr-4 text-text-secondary whitespace-nowrap">{formatDate(ds.last_scraped_at || ds.created_at)}</td>
                    <td className="py-3">
                      <ActionMenu dataset={ds} onDelete={() => setDeleteTarget(ds)} onRescrape={() => rescrapeMutation.mutate(ds.id)} />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </main>
      </div>
    </AuthGuard>
  )
}

'use client'

import { useState, useRef, useEffect } from 'react'
import Link from 'next/link'
import { useParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { AuthGuard } from '@/components/layout/AuthGuard'
import { TopNav } from '@/components/layout/TopNav'
import { StatusBadge } from '@/components/ui/StatusBadge'
import { datasetsApi, chatApi } from '@/lib/api'
import { ChatMessage, Dataset } from '@/types'
import { Send, ArrowLeft } from 'lucide-react'

const SUGGESTIONS = [
  'What are the most common complaints?',
  'What do reviewers say about quality?',
  'What features do customers love most?',
]

function ChatBubble({ msg }: { msg: ChatMessage }) {
  if (msg.role === 'user') {
    return (
      <div className="flex justify-end mb-4">
        <div className="max-w-[75%] bg-accent text-white rounded-xl rounded-tr-sm px-4 py-3 text-sm">
          {msg.content}
        </div>
      </div>
    )
  }

  if (msg.scope_refused) {
    return (
      <div className="flex justify-start mb-4">
        <div className="max-w-[75%] bg-scope-guard-bg border border-dashed border-scope-guard-border rounded-xl px-4 py-3 text-sm text-text-secondary italic">
          {msg.content}
        </div>
      </div>
    )
  }

  return (
    <div className="flex justify-start mb-4">
      <div className="max-w-[75%] bg-surface border border-border rounded-xl rounded-tl-sm px-4 py-3 text-sm shadow-sm">
        <div className="text-xs text-text-secondary mb-1">ReviewLens AI</div>
        <div className="whitespace-pre-wrap">{msg.content}</div>
      </div>
    </div>
  )
}

export default function ChatPage() {
  const { id } = useParams<{ id: string }>()
  const [messages, setMessages] = useState<ChatMessage[]>([])
  const [input, setInput] = useState('')
  const [sending, setSending] = useState(false)
  const [error, setError] = useState('')
  const bottomRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLTextAreaElement>(null)

  const { data: ds } = useQuery({
    queryKey: ['dataset', id],
    queryFn: () => datasetsApi.get(id),
  })

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  useEffect(() => {
    inputRef.current?.focus()
  }, [])

  const sendMessage = async (text: string) => {
    if (!text.trim() || sending) return
    setError('')
    const userMsg: ChatMessage = { role: 'user', content: text }
    setMessages(prev => [...prev, userMsg])
    setInput('')
    setSending(true)

    try {
      const history = messages.slice(-10)
      const res = await chatApi.send(id, text, history)
      setMessages(prev => [...prev, {
        role: 'assistant',
        content: res.reply,
        scope_refused: res.scope_refused,
      }])
    } catch (err: any) {
      setError(err?.data?.message || 'Something went wrong. Please try again.')
      setMessages(prev => [...prev, {
        role: 'assistant',
        content: 'Something went wrong. Please try again.',
        scope_refused: false,
      }])
    } finally {
      setSending(false)
      inputRef.current?.focus()
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      sendMessage(input)
    }
  }

  return (
    <AuthGuard>
      <div className="flex flex-col h-screen">
        <TopNav />
        <div className="flex flex-1 overflow-hidden">
          {/* Sidebar */}
          <aside className="w-56 border-r border-border bg-surface flex flex-col shrink-0">
            <div className="flex-1 overflow-y-auto py-3">
              {ds && (
                <Link href={`/datasets/${id}`} className="flex items-center gap-2 px-4 py-2.5 text-sm bg-accent-subtle border-l-[3px] border-accent text-accent font-medium hover:bg-accent/10 transition-colors">
                  <span className="w-1.5 h-1.5 rounded-full shrink-0 bg-accent" />
                  <span className="truncate">{ds.product_name || ds.asin}</span>
                </Link>
              )}
            </div>
            <div className="p-4 border-t border-border">
              <Link href="/datasets" className="flex items-center gap-1.5 text-sm text-text-secondary hover:text-text-primary">
                <ArrowLeft size={14} /> All Datasets
              </Link>
            </div>
          </aside>

          {/* Chat panel */}
          <div className="flex-1 flex flex-col overflow-hidden">
            {/* Context header */}
            {ds && (
              <div className="px-6 py-3 border-b border-border bg-white">
                <div className="flex items-center gap-3">
                  <span className="font-semibold text-text-primary">{ds.product_name || ds.asin}</span>
                  <StatusBadge status={ds.status} />
                  {ds.review_count && <span className="text-xs text-text-secondary">{ds.review_count.toLocaleString()} reviews</span>}
                </div>
              </div>
            )}

            {/* Messages */}
            <div className="flex-1 overflow-y-auto px-6 py-4" aria-live="polite">
              {messages.length === 0 && (
                <div className="flex flex-col items-center justify-center h-full gap-4">
                  <p className="text-text-secondary text-sm">Ask a question about these reviews</p>
                  <div className="flex flex-wrap gap-2 justify-center max-w-md">
                    {SUGGESTIONS.map(s => (
                      <button
                        key={s}
                        onClick={() => sendMessage(s)}
                        className="px-3 py-2 text-xs border border-border rounded-full hover:bg-raised text-text-secondary hover:text-text-primary transition-colors"
                      >
                        {s}
                      </button>
                    ))}
                  </div>
                </div>
              )}
              {messages.map((msg, i) => <ChatBubble key={i} msg={msg} />)}
              {sending && (
                <div className="flex justify-start mb-4">
                  <div className="bg-surface border border-border rounded-xl rounded-tl-sm px-4 py-3">
                    <div className="flex gap-1">
                      <div className="w-1.5 h-1.5 bg-text-secondary rounded-full animate-bounce [animation-delay:0ms]" />
                      <div className="w-1.5 h-1.5 bg-text-secondary rounded-full animate-bounce [animation-delay:150ms]" />
                      <div className="w-1.5 h-1.5 bg-text-secondary rounded-full animate-bounce [animation-delay:300ms]" />
                    </div>
                  </div>
                </div>
              )}
              <div ref={bottomRef} />
            </div>

            {/* Input */}
            <div className="px-6 py-4 border-t border-border bg-white">
              <div className="flex items-end gap-3 border border-border rounded-xl overflow-hidden bg-white focus-within:ring-2 focus-within:ring-accent">
                <textarea
                  ref={inputRef}
                  value={input}
                  onChange={e => setInput(e.target.value)}
                  onKeyDown={handleKeyDown}
                  placeholder="Ask a question about these reviews…"
                  rows={1}
                  className="flex-1 px-4 py-3 text-sm resize-none focus:outline-none bg-transparent"
                  style={{ maxHeight: '112px', overflowY: 'auto' }}
                  disabled={sending || ds?.status !== 'ready'}
                />
                <button
                  onClick={() => sendMessage(input)}
                  disabled={!input.trim() || sending || ds?.status !== 'ready'}
                  className="mr-3 mb-3 w-8 h-8 bg-accent text-white rounded-lg flex items-center justify-center hover:bg-accent-hover disabled:opacity-40 transition-colors"
                  aria-label="Send"
                >
                  <Send size={14} />
                </button>
              </div>
              <p className="text-xs text-text-disabled mt-1">Enter to send · Shift+Enter for newline</p>
            </div>
          </div>
        </div>
      </div>
    </AuthGuard>
  )
}

